#!/usr/bin/env node
// Generates backend/benchmarks/configs.generated.js and src/generated/benchmarkRegistry.js
// from the single hand-edited source: shared/benchmark-registry.json
//
// Usage:
//   node scripts/generate-benchmark-config.js          # write generated files
//   node scripts/generate-benchmark-config.js --check  # exit 1 if generated files are stale

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const REGISTRY_PATH = path.join(ROOT, 'shared', 'benchmark-registry.json');
const BACKEND_OUT = path.join(ROOT, 'backend', 'benchmarks', 'configs.generated.js');
const FRONTEND_OUT = path.join(ROOT, 'src', 'generated', 'benchmarkRegistry.js');

const HEADER = `// AUTO-GENERATED by scripts/generate-benchmark-config.js — DO NOT EDIT BY HAND.
// Source of truth: shared/benchmark-registry.json
// Run \`npm run config:generate\` after editing the registry to refresh this file.
`;

function loadRegistry() {
  const raw = fs.readFileSync(REGISTRY_PATH, 'utf8');
  return JSON.parse(raw);
}

function buildMultipliers(configurations) {
  const multipliers = {};
  for (const cfg of configurations) {
    multipliers[cfg.id] = cfg.multiplier;
  }
  return multipliers;
}

function renderBackend(registry) {
  const { configurations, machineProfiles, wasmLoaderConfigs } = registry;
  const multipliers = buildMultipliers(configurations);
  const configsNoMultiplier = configurations.map(({ multiplier, ...rest }) => rest);

  return `${HEADER}
const configurations = ${JSON.stringify(configsNoMultiplier, null, 2)};

const multipliers = ${JSON.stringify(multipliers, null, 2)};

const wasmLoaderConfigs = ${JSON.stringify(wasmLoaderConfigs, null, 2)};

const machineProfiles = ${JSON.stringify(machineProfiles, null, 2)};

module.exports = { configurations, multipliers, wasmLoaderConfigs, machineProfiles };
`;
}

function renderFrontend(registry) {
  const { configurations, machineProfiles, wasmLoaderConfigs } = registry;
  const multipliers = buildMultipliers(configurations);
  const configsNoMultiplier = configurations.map(({ multiplier, ...rest }) => rest);

  return `${HEADER}
export const configurations = ${JSON.stringify(configsNoMultiplier, null, 2)};

export const multipliers = ${JSON.stringify(multipliers, null, 2)};

export const wasmLoaderConfigs = ${JSON.stringify(wasmLoaderConfigs, null, 2)};

export const machineProfiles = ${JSON.stringify(machineProfiles, null, 2)};
`;
}

function main() {
  const check = process.argv.includes('--check');
  const registry = loadRegistry();

  const outputs = [
    [BACKEND_OUT, renderBackend(registry)],
    [FRONTEND_OUT, renderFrontend(registry)],
  ];

  if (check) {
    let stale = false;
    for (const [outPath, content] of outputs) {
      const existing = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : null;
      if (existing !== content) {
        console.error(`Stale or missing generated file: ${path.relative(ROOT, outPath)}`);
        stale = true;
      }
    }
    if (stale) {
      console.error('\nRun `npm run config:generate` and commit the result.');
      process.exit(1);
    }
    console.log('Generated benchmark config files are up to date.');
    return;
  }

  for (const [outPath, content] of outputs) {
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, content);
    console.log(`Wrote ${path.relative(ROOT, outPath)}`);
  }
}

main();
